%* Example 1: Show help information: ;
%m_utl_chg_delimiter(?)

%* Example 2: Change a blank delimited list into a comma separated list: ;
proc sql noprint;
   select Name
     into :girls separated by ' '
     from SASHELP.class
    where Sex='F'
   ;
quit;

%put &=girls.;

%let list=
   %m_utl_chg_delimiter(
      list   = %str(&girls.)
    , newdlm = %str(, )
    , debug  = Y
      );

%put &=list.;


%* Example 3: Change a blank delimited list into a single quoted and comma separated list: ;
proc sql noprint;
   select Name
     into :girls separated by ' '
     from SASHELP.class
    where Sex='F'
   ;
quit;

%put &=girls.;

%let list=
   %m_utl_chg_delimiter(
      list   = %str(&girls.)
    , newdlm = %str(', ')
    , quotes = SINGLE
    , debug  = Y
      );

%put &=list.;

proc print data=SASHELP.class(where=(Name in (&list.)));
run;


%* Example 4: Change a multi separated list into a single comma separated list: ;
%let list=
   %m_utl_chg_delimiter(
      list   = %str(James,Jeffrey#John Philip,Robert)
    , dlm    = %str(,# )
    , newdlm = %str(", ")
    , quotes = Y
    , debug  = Y
      );

%put &=list.;

proc print data=SASHELP.class(where=(Name in (&list.)));
run;


%* Example 5: Change a name-quotes comma separated list into a blank separated list: ;
data WORK.class;
   set SASHELP.class;
   rename
      name = 'Name (Student)'n
      sex  = 'Gender (F/M)'n
      age  = 'Age (Years)'n
      ;
run;

%let list=
   %m_utl_chg_delimiter(
      list   = %str('Name (Student)'n,'Gender (F/M)'n,'Age (Years)'n)
    , dlm    = %str(,)
    , newdlm = %str( )
    , quotes = N
    , debug  = Y
      );

%put &=list.;

proc print data=WORK.class (keep=&list.);
run;

