proc sort data=WORK.trans1 nodupkey
   out=WORK.trans1(index=(tkey1));
   by descending tkey1;
run;

proc sort data=WORK.trans2 nodupkey
   out=WORK.trans2(index=(tkey2));
   by descending tkey2;
run;

proc sort data=WORK.trans3 nodupkey
   out=WORK.trans3(index=(tkey3));
   by descending tkey3;
run;

%* Example 2: Step 3 - Join Master and Lookup tables by data step set key=: ;
%let _start = %sysfunc(datetime());

data WORK.master_keyjoin;
   set WORK.master;
   %m_utl_join_setkey(
      master_key  = mkey1
    , table       = WORK.trans1
    , key         = tkey1
    , key_num     = 1
    , default_key = 0
    , debug       = Y
      )
   %m_utl_join_setkey(
      master_key  = mkey2
    , table       = WORK.trans2
    , key         = tkey2
    , key_num     = 2
    , exclude     = trans2_txt
    , default_key = 0
    , debug       = Y
      )
   %m_utl_join_setkey(
      master_key  = mkey3
    , table       = WORK.trans3
    , key         = tkey3
    , key_num     = 3
    , rename_from = trans3_txt2
    , rename_to   = trans3_num
    , default_key = 0
    , debug       = Y
      )
   output;
run;

%let _stop = %sysfunc(datetime());
%let _time = %sysfunc(intck(SECOND, &_start., &_stop.), time10.);

data WORK.result;
   RunType="KEY Join";
   Message="Total Processing time for KEY join: &_time. (hh:mm:ss)";
run;

proc print data=WORK.result noobs;
run;

%* Example 2: Step 4 - Join Master and Lookup tables by proc sql join: ;
%let _start = %sysfunc(datetime());

proc sql noprint nothreads;
   create table WORK.mtemp_1 as
   select m.*
        , t.*
     from WORK.master m
          left join WORK.trans1 t
       on m.mkey1 = t.tkey1
          ;
   create table WORK.mtemp_2 as
   select m.*
        , t.*
     from WORK.mtemp_1 m
          left join WORK.trans2(drop=trans2_txt) t
       on m.mkey2 = t.tkey2
          ;
   create table WORK.master_sqljoin as
   select m.*
        , t.*
     from WORK.mtemp_2 m
          left join WORK.trans3(rename=(trans3_txt2=trans3_num)) t
       on m.mkey3 = t.tkey3
          ;
quit;

